				controlContenedor.addItem(controles[numControl].id() + "  (" + controles[numControl].name() + ")", controles[numControl].id());
			};

			// Seleccionar el valor del combo
			controlContenedor.setCurrentIndex(controlContenedor.findData(theRegisterIn.fieldToString("CNT_ID")));
		};
	};
};

#include "(CurrentProject)/js/personaliza/personaWizard.js"

// ------------------------
// Cargar los controles
// ------------------------

// Atrapar el subformulario donde están los controles
var formularioPadre = theRoot.dataView();
var separador = formularioPadre.control("SEP");
var formularioObjetos = separador.form("sygemat_corralon_app/PRS_OBJ_W_OBJ");
var formularioControles = separador.form("sygemat_corralon_app/PRS_OBJ_W_CTL");

// Limpiar la tabla en memoria de controles
var listaControles = new VRegisterList(theRoot);
listaControles.setTable("sygemat_corralon_dat/PRS_CTR_W");
listaControles.load("ID", []);
listaControles.remove(listaControles);

// Actualizar la rejilla (Por si no se cargan controles para que se limpie
var rejillaControles = formularioControles.control("CTL");
rejillaControles.clear();

// Leer el proyecto seleccionado
var controlProyecto = formularioObjetos.control("PRY");
if (controlProyecto)
{	
	var proyectoInfo = theApp.projectInfo(controlProyecto.itemData(controlProyecto.currentIndex));
	var objetoInfo = proyectoInfo.objectInfo(theRegisterIn.fieldToString("OBJ_TIP"), theRegisterIn.fieldToString("OBJ_ID"));
	if (objetoInfo)
	{	
		// Se abre transacción si no existe
        transCurso = theRoot.existTrans();
	    if (transCurso == false)
        {
            var transNueva = theRoot.beginTrans("Creando controles en tabla en memoria");
        };

		if (transCurso || transNueva)
		{
			// Se recorren los controles del formulario o las columnas de la rejilla
			var tipoSubobjetos = (theRegisterIn.fieldToString("OBJ_TIP") == VObjectInfo.TypeForm) ? VObjectInfo.TypeControl : VObjectInfo.TypeGridCol;
			var subobjetosSeleccionados = theRegisterIn.fieldToString("SUB_OBJ").split(",");

			for (var numControl = 0; numControl < objetoInfo.subObjectCount(tipoSubobjetos); numControl++)
			{
				var control = objetoInfo.subObjectInfo(tipoSubobjetos, numControl);			
				if (control)
				{	
					// Se preparan los datos del control
					var controlId = control.id();
					var controlName = control.name();

					// Se crear el registro del control en la tabla en memoria
					var registro = new VRegister(theRoot);
					registro.setTable("sygemat_corralon_dat/PRS_CTR_W");
					registro.setField("CTL_ID", controlId);
					registro.setField("NAME", controlName);
					registro.setField("POS", numControl);					
					registro.addRegister();
					listaControles.append(registro);

					// Añadir el registro a la lista y marcarlo como seleccionado si procede
					rejillaControles.append(registro);
					var datoSeleccionado = (theRegisterIn.fieldToString("OBJ_TIP") == VObjectInfo.TypeForm) ? controlId : numControl.toString();

					if (subobjetosSeleccionados.indexOf(datoSeleccionado) != -1)
					{
						rejillaControles.addToMultiSelection(registro);
					};
				};
			};

			// Se cierra la transacción si se creó una nueva
			if (transNueva)
			{
				theRoot.commitTrans();
			};
		};
	};		
};

