#include "(CurrentProject)/js/personaliza/personaWizard.js"

// --------------------------------------------
// Cargar los objetos del nuevo proyecto
// --------------------------------------------

// Atrapar el subformulario donde están los controles
var formularioPadre = theRoot.dataView();
var separador = formularioPadre.control("SEP");
var formulario = separador.form("sygemat_corralon_app/PRS_OBJ_W_OBJ");

// Leer el proyecto seleccionado
var controlProyecto = formulario.control("PRY_NEW");
if (controlProyecto)
{
	var proyectoInfo = theApp.projectInfo(controlProyecto.itemData(controlProyecto.currentIndex));
};

// Cargar objetos en el combobox
var objetosInfo = getObjetosProyectoTipoInfo(proyectoInfo, theRegisterIn.fieldToInt("OBJ_TIP"));
var controlObjeto = formulario.control("OBJ_NEW_ID");
if (controlObjeto)
{
	// Se limpia el contenido antes de añadir el nuevo
	controlObjeto.clear();

	// Leemos la tabla del formulario de origen
	var proyectoOrigen = theApp.projectInfo(theRegisterIn.fieldToString("PRY"));
	var formularioOrigenId = theRegisterIn.fieldToString("OBJ_ID_REF").slice(theRegisterIn.fieldToString("OBJ_ID_REF").indexOf("/") + 1);
	var formularioOrigenInfo = proyectoOrigen.objectInfo(VObjectInfo.TypeForm, formularioOrigenId);
	var tablaOrigen = formularioOrigenInfo.inputTable();

	// Se añaden los formularios del proyecto seleccionado
	for(numObjeto in objetosInfo)
	{
		var tablaNuevo = objetosInfo[numObjeto].inputTable();
		if ((tablaNuevo == tablaOrigen) || (tablaNuevo.id() == ""))
		{
			controlObjeto.addItem(objetosInfo[numObjeto].id() + "  (" + objetosInfo[numObjeto].name() + ")", objetosInfo[numObjeto].id());
		} else 
		{
			// Si la tabla es diferente se compreba si es tabla de extensión de la de origen para añadir también el subformulario
			// Miro si el campo ID es puntero a la tabla de origen, si son iguales se carga
			var campoIdNumero = tablaNuevo.findField("ID");
			var campoIdTabla = tablaNuevo.fieldBoundedTableInfo(campoIdNumero);
			if (campoIdTabla == tablaOrigen)
			{
				controlObjeto.addItem(objetosInfo[numObjeto].id() + "  (" + objetosInfo[numObjeto].name() + ")", objetosInfo[numObjeto].id());
			};
		};
	};

	controlObjeto.setCurrentIndex(controlObjeto.findData(theRegisterIn.fieldToString("OBJ_NEW_ID")));
};

