// ------------------------------------
// Cargar proyectos en combobox
// ------------------------------------

// Atrapar el subformulario donde están los controles
var formularioPadre = theRoot.dataView();
var separador = formularioPadre.control("SEP");
var formulario = separador.form("sygemat_corralon_app/PRS_OBJ_W_OBJ");

// Preparar los arrays
var proyectosInfo = [];
var proyectosAlias = [];
var proyectosId = [];
getProyectosHeredadosInfo(theApp.mainProjectInfo(), proyectosInfo, proyectosAlias, proyectosId);

// Se preparan los 2 combobox para cargar los proyectos
var controlProyecto = formulario.control("PRY");
var controlProyectoNuevo = formulario.control("PRY_NEW");

// Limpiar el contenido de los controles
controlProyecto.clear();
controlProyectoNuevo.clear();

// Cargar los proyectos en los controles
for(numProyecto in proyectosInfo)
{
	// Se cargan sólo los proyectos de aplicación
	if (proyectosInfo[numProyecto].type() == VProjectInfo.TypeApp)
	{
		controlProyecto.addItem(proyectosInfo[numProyecto].name(), proyectosInfo[numProyecto].alias());
		controlProyectoNuevo.addItem(proyectosInfo[numProyecto].name(), proyectosInfo[numProyecto].alias());			
	};
};

controlProyecto.setCurrentIndex(controlProyecto.findData(theRegisterIn.fieldToString("PRY")));
controlProyectoNuevo.setCurrentIndex(controlProyectoNuevo.findData(theRegisterIn.fieldToString("PRY_NEW")));

